      // Add user defined key bindings.\\n        exCommandDispatcher.map(lhs, rhs, ctx);\\n      },\\n      unmap: function(lhs, ctx) {\\n        exCommandDispatcher.unmap(lhs, ctx);\\n      },\\n      // Non-recursive map function.\\n      // NOTE: This will not create mappings to key maps that aren't present\\n      // in the default key map. See TODO at bottom of function.\\n      noremap: function(lhs, rhs, ctx) {\\n        function toCtxArray(ctx) {\\n          return ctx ? [ctx] : ['normal', 'insert', 'visual'];\\n        }\\n        var ctxsToMap = toCtxArray(ctx);\\n        // Look through all actual defaults to find a map candidate.\\n        var actualLength = defaultKeymap.length, origLength = defaultKeymapLength;\\n        for (var i = actualLength - origLength;\\n             i < actualLength && ctxsToMap.length;\\n             i++) {\\n          var mapping = defaultKeymap[i];\\n          // Omit mappings that operate in the wrong context(s) and those of invalid type.\\n          if (mapping.keys == rhs &&\\n              (!ctx || !mapping.context || mapping.context === ctx) &&\\n              mapping.type.substr(0, 2) !== 'ex' &&\\n              mapping.type.substr(0, 3) !== 'key') {\\n            // Make a shallow copy of the original keymap entry.\\n            var newMapping = {};\\n            for (var key in mapping) {\\n              newMapping[key] = mapping[key];\\n            }\\n            // Modify it point to the new mapping with the proper context.\\n            newMapping.keys = lhs;\\n            if (ctx && !newMapping.context) {\\n              newMapping.context = ctx;\\n            }\\n            // Add it to the keymap with a higher priority than the original.\\n            this._mapCommand(newMapping);\\n            // Record the mapped contexts as complete.\\n            var mappedCtxs = toCtxArray(mapping.context);\\n            ctxsToMap = ctxsToMap.filter(function(el) { return mappedCtxs.indexOf(el) === -1; });\\n          }\\n        }\\n        // TODO: Create non-recursive keyToKey mappings for the unmapped contexts once those exist.\\n      },\\n      // Remove all user-defined mappings for the provided context.\\n      mapclear: function(ctx) {\\n        // Partition the existing keymap into user-defined and true defaults.\\n        var actualLength = defaultKeymap.length,\\n            origLength = defaultKeymapLength;\\n        var userKeymap = defaultKeymap.slice(0, actualLength - origLength);\\n        defaultKeymap = defaultKeymap.slice(actualLength - origLength);\\n        if (ctx) {\\n          // If a specific context is being cleared, we need to keep mappings\\n          // from all other contexts.\\n          for (var i = userKeymap.length - 1; i >= 0; i--) {\\n            var mapping = userKeymap[i];\\n            if (ctx !== mapping.context) {\\n              if (mapping.context) {\\n                this._mapCommand(mapping);\\n              } else {\\n                // `mapping` applies to all contexts so create keymap copies\\n                // for each context except the one being cleared.\\n                var contexts = ['normal', 'insert', 'visual'];\\n                for (var j in contexts) {\\n                  if (contexts[j] !== ctx) {\\n                    var newMapping = {};\\n                    for (var key in mapping) {\\n                      newMapping[key] = mapping[key];\\n                    }\\n                    newMapping.context = contexts[j];\\n                    this._mapCommand(newMapping);\\n                  }\\n                }\\n              }\\n            }\\n          }\\n        }\\n      },\\n      // TODO: Expose setOption and getOption as instance methods. Need to decide how to namespace\\n      // them, or somehow make them work with the existing CodeMirror setOption/getOption API.\\n      setOption: setOption,\\n      getOption: getOption,\\n      defineOption: defineOption,\\n      defineEx: function(name, prefix, func){\\n        if (!prefix) {\\n          prefix = name;\\n        } else if (name.indexOf(prefix) !== 0) {\\n          throw new Error('(Vim.defineEx) \\\"'+prefix+'\\\" is not a prefix of \\\"'+name+'\\\", command not registered');\\n        }\\n        exCommands[name]=func;\\n        exCommandDispatcher.commandMap_[prefix]={name:name, shortName:prefix, type:'api'};\\n      },\\n      handleKey: function (cm, key, origin) {\\n        var command = this.findKey(cm, key, origin);\\n        if (typeof command === 'function') {\\n          return command();\\n        }\\n      },\\n      /**\\n       * This is the outermost function called by CodeMirror, after keys have\\n       * been mapped to their Vim equivalents.\\n       *\\n       * Finds a command based on the key (and cached keys if there is a\\n       * multi-key sequence). Returns `undefined` if no key is matched, a noop\\n       * function if a partial match is found (multi-key), and a function to\\n       * execute the bound command if a a key is matched. The function always\\n       * returns true.\\n       */\\n      findKey: function(cm, key, origin) {\\n        var vim = maybeInitVimState(cm);\\n        function handleMacroRecording() {\\n          var macroModeState = vimGlobalState.macroModeState;\\n          if (macroModeState.isRecording) {\\n            if (key == 'q') {\\n              macroModeState.exitMacroRecordMode();\\n              clearInputState(cm);\\n              return true;\\n            }\\n            if (origin != 'mapping') {\\n              logKey(macroModeState, key);\\n            }\\n          }\\n        }\\n        function handleEsc() {\\n          if (key == '<Esc>') {\\n            // Clear input state and get back to normal mode.\\n            clearInputState(cm);\\n            if (vim.visualMode) {\\n              exitVisualMode(cm);\\n            } else if (vim.insertMode) {\\n              exitInsertMode(cm);\\n            }\\n            return true;\\n          }\\n        }\\n        function doKeyToKey(keys) {\\n          // TODO: prevent infinite recursion.\\n          var match;\\n          while (keys) {\\n            // Pull off one command key, which is either a single character\\n            // or a special sequence wrapped in '<' and '>', e.g. '<Space>'.\\n            match = (/<\\\\w+-.+?>|<\\\\w+>|./).exec(keys);\\n            key = match[0];\\n            keys = keys.substring(match.index + key.length);\\n            CodeMirror.Vim.handleKey(cm, key, 'mapping');\\n          }\\n        }\\n\\n        function handleKeyInsertMode() {\\n          if (handleEsc()) { return true; }\\n          var keys = vim.inputState.keyBuffer = vim.inputState.keyBuffer + key;\\n          var keysAreChars = key.length == 1;\\n          var match = commandDispatcher.matchCommand(keys, defaultKeymap, vim.inputState, 'insert');\\n          // Need to check all key substrings in insert mode.\\n          while (keys.length > 1 && match.type != 'full') {\\n            var keys = vim.inputState.keyBuffer = keys.slice(1);\\n            var thisMatch = commandDispatcher.matchCommand(keys, defaultKeymap, vim.inputState, 'insert');\\n            if (thisMatch.type != 'none') { match = thisMatch; }\\n          }\\n          if (match.type == 'none') { clearInputState(cm); return false; }\\n          else if (match.type == 'partial') {\\n            if (lastInsertModeKeyTimer) { window.clearTimeout(lastInsertModeKeyTimer); }\\n            lastInsertModeKeyTimer = window.setTimeout(\\n              function() { if (vim.insertMode && vim.inputState.keyBuffer) { clearInputState(cm); } },\\n              getOption('insertModeEscKeysTimeout'));\\n            return !keysAreChars;\\n          }\\n\\n          if (lastInsertModeKeyTimer) { window.clearTimeout(lastInsertModeKeyTimer); }\\n          if (keysAreChars) {\\n            var selections = cm.listSelections();\\n            for (var i = 0; i < selections.length; i++) {\\n              var here = selections[i].head;\\n              cm.replaceRange('', offsetCursor(here, 0, -(keys.length - 1)), here, '+input');\\n            }\\n            vimGlobalState.macroModeState.lastInsertModeChanges.changes.pop();\\n          }\\n          clearInputState(cm);\\n          return match.command;\\n        }\\n\\n        function handleKeyNonInsertMode() {\\n          if (handleMacroRecording() || handleEsc()) { return true; }\\n\\n          var keys = vim.inputState.keyBuffer = vim.inputState.keyBuffer + key;\\n          if (/^[1-9]\\\\d*$/.test(keys)) { return true; }\\n\\n          var keysMatcher = /^(\\\\d*)(.*)$/.exec(keys);\\n          if (!keysMatcher) { clearInputState(cm); return false; }\\n          var context = vim.visualMode ? 'visual' :\\n                                         'normal';\\n          var match = commandDispatcher.matchCommand(keysMatcher[2] || keysMatcher[1], defaultKeymap, vim.inputState, context);\\n          if (match.type == 'none') { clearInputState(cm); return false; }\\n          else if (match.type == 'partial') { return true; }\\n\\n          vim.inputState.keyBuffer = '';\\n          var keysMatcher = /^(\\\\d*)(.*)$/.exec(keys);\\n          if (keysMatcher[1] && keysMatcher[1] != '0') {\\n            vim.inputState.pushRepeatDigit(keysMatcher[1]);\\n          }\\n          return match.command;\\n        }\\n\\n        var command;\\n        if (vim.insertMode) { command = handleKeyInsertMode(); }\\n        else { command = handleKeyNonInsertMode(); }\\n        if (command === false) {\\n          return !vim.insertMode && key.length === 1 ? function() { return true; } : undefined;\\n        } else if (command === true) {\\n          // TODO: Look into using CodeMirror's multi-key handling.\\n          // Return no-op since we are caching the key. Counts as handled, but\\n          // don't want act on it just yet.\\n          return function() { return true; };\\n        } else {\\n          return function() {\\n            return cm.operation(function() {\\n              cm.curOp.isVimOp = true;\\n              try {\\n                if (command.type == 'keyToKey') {\\n                  doKeyToKey(command.toKeys);\\n                } else {\\n                  commandDispatcher.processCommand(cm, vim, command);\\n                }\\n              } catch (e) {\\n                // clear VIM state in case it's in a bad state.\\n                cm.state.vim = undefined;\\n                maybeInitVimState(cm);\\n                if (!CodeMirror.Vim.suppressErrorLogging) {\\n                  console['log'](e);\\n                }\\n                throw e;\\n              }\\n              return true;\\n            });\\n          };\\n        }\\n      },\\n      handleEx: function(cm, input) {\\n        exCommandDispatcher.processCommand(cm, input);\\n      },\\n\\n      defineMotion: defineMotion,\\n      defineAction: defineAction,\\n      defineOperator: defineOperator,\\n      mapCommand: mapCommand,\\n      _mapCommand: _mapCommand,\\n\\n      defineRegister: defineRegister,\\n\\n      exitVisualMode: exitVisualMode,\\n      exitInsertMode: exitInsertMode\\n    };\\n\\n    // Represents the current input state.\\n    function InputState() {\\n      this.prefixRepeat = [];\\n      this.motionRepeat = [];\\n\\n      this.operator = null;\\n      this.operatorArgs = null;\\n      this.motion = null;\\n      this.motionArgs = null;\\n      this.keyBuffer = []; // For matching multi-key commands.\\n      this.registerName = null; // Defaults to the unnamed register.\\n    }\\n    InputState.prototype.pushRepeatDigit = function(n) {\\n      if (!this.operator) {\\n        this.prefixRepeat = this.prefixRepeat.concat(n);\\n      } else {\\n        this.motionRepeat = this.motionRepeat.concat(n);\\n      }\\n    };\\n    InputState.prototype.getRepeat = function() {\\n      var repeat = 0;\\n      if (this.prefixRepeat.length > 0 || this.motionRepeat.length > 0) {\\n        repeat = 1;\\n        if (this.prefixRepeat.length > 0) {\\n          repeat *= parseInt(this.prefixRepeat.join(''), 10);\\n        }\\n        if (this.motionRepeat.length > 0) {\\n          repeat *= parseInt(this.motionRepeat.join(''), 10);\\n        }\\n      }\\n      return repeat;\\n    };\\n\\n    function clearInputState(cm, reason) {\\n      cm.state.vim.inputState = new InputState();\\n      CodeMirror.signal(cm, 'vim-command-done', reason);\\n    }\\n\\n    /*\\n     * Register stores information about copy and paste registers.  Besides\\n     * text, a register must store whether it is linewise (i.e., when it is\\n     * pasted, should it insert itself into a new line, or should the text be\\n     * inserted at the cursor position.)\\n     */\\n    function Register(text, linewise, blockwise) {\\n      this.clear();\\n      this.keyBuffer = [text || ''];\\n      this.insertModeChanges = [];\\n      this.searchQueries = [];\\n      this.linewise = !!linewise;\\n      this.blockwise = !!blockwise;\\n    }\\n    Register.prototype = {\\n      setText: function(text, linewise, blockwise) {\\n        this.keyBuffer = [text || ''];\\n        this.linewise = !!linewise;\\n        this.blockwise = !!blockwise;\\n      },\\n      pushText: function(text, linewise) {\\n        // if this register has ever been set to linewise, use linewise.\\n        if (linewise) {\\n          if (!this.linewise) {\\n            this.keyBuffer.push('\\\\n');\\n          }\\n          this.linewise = true;\\n        }\\n        this.keyBuffer.push(text);\\n      },\\n      pushInsertModeChanges: function(changes) {\\n        this.insertModeChanges.push(createInsertModeChanges(changes));\\n      },\\n      pushSearchQuery: function(query) {\\n        this.searchQueries.push(query);\\n      },\\n      clear: function() {\\n        this.keyBuffer = [];\\n        this.insertModeChanges = [];\\n        this.searchQueries = [];\\n        this.linewise = false;\\n      },\\n      toString: function() {\\n        return this.keyBuffer.join('');\\n      }\\n    };\\n\\n    /**\\n     * Defines an external register.\\n     *\\n     * The name should be a single character that will be used to reference the register.\\n     * The register should support setText, pushText, clear, and toString(). See Register\\n     * for a reference implementation.\\n     */\\n    function defineRegister(name, register) {\\n      var registers = vimGlobalState.registerController.registers;\\n      if (!name || name.length != 1) {\\n        throw Error('Register name must be 1 character');\\n      }\\n      if (registers[name]) {\\n        throw Error('Register already defined ' + name);\\n      }\\n      registers[name] = register;\\n      validRegisters.push(name);\\n    }\\n\\n    /*\\n     * vim registers allow you to keep many independent copy and paste buffers.\\n     * See http://usevim.com/2012/04/13/registers/ for an introduction.\\n     *\\n     * RegisterController keeps the state of all the registers.  An initial\\n     * state may be passed in.  The unnamed register '\\\"' will always be\\n     * overridden.\\n     */\\n    function RegisterController(registers) {\\n      this.registers = registers;\\n      this.unnamedRegister = registers['\\\"'] = new Register();\\n      registers['.'] = new Register();\\n      registers[':'] = new Register();\\n      registers['/'] = new Register();\\n    }\\n    RegisterController.prototype = {\\n      pushText: function(registerName, operator, text, linewise, blockwise) {\\n        if (linewise && text.charAt(text.length - 1) !== '\\\\n'){\\n          text += '\\\\n';\\n        }\\n        // Lowercase and uppercase registers refer to the same register.\\n        // Uppercase just means append.\\n        var register = this.isValidRegister(registerName) ?\\n            this.getRegister(registerName) : null;\\n        // if no register/an invalid register was specified, things go to the\\n        // default registers\\n        if (!register) {\\n          switch (operator) {\\n            case 'yank':\\n              // The 0 register contains the text from the most recent yank.\\n              this.registers['0'] = new Register(text, linewise, blockwise);\\n              break;\\n            case 'delete':\\n            case 'change':\\n              if (text.indexOf('\\\\n') == -1) {\\n                // Delete less than 1 line. Update the small delete register.\\n                this.registers['-'] = new Register(text, linewise);\\n              } else {\\n                // Shift down the contents of the numbered registers and put the\\n                // deleted text into register 1.\\n                this.shiftNumericRegisters_();\\n                this.registers['1'] = new Register(text, linewise);\\n              }\\n              break;\\n          }\\n          // Make sure the unnamed register is set to what just happened\\n          this.unnamedRegister.setText(text, linewise, blockwise);\\n          return;\\n        }\\n\\n        // If we've gotten to this point, we've actually specified a register\\n        var append = isUpperCase(registerName);\\n        if (append) {\\n          register.pushText(text, linewise);\\n        } else {\\n          register.setText(text, linewise, blockwise);\\n        }\\n        // The unnamed register always has the same value as the last used\\n        // register.\\n        this.unnamedRegister.setText(register.toString(), linewise);\\n      },\\n      // Gets the register named @name.  If one of @name doesn't already exist,\\n      // create it.  If @name is invalid, return the unnamedRegister.\\n      getRegister: function(name) {\\n        if (!this.isValidRegister(name)) {\\n          return this.unnamedRegister;\\n        }\\n        name = name.toLowerCase();\\n        if (!this.registers[name]) {\\n          this.registers[name] = new Register();\\n        }\\n        return this.registers[name];\\n      },\\n      isValidRegister: function(name) {\\n        return name && inArray(name, validRegisters);\\n      },\\n      shiftNumericRegisters_: function() {\\n        for (var i = 9; i >= 2; i--) {\\n          this.registers[i] = this.getRegister('' + (i - 1));\\n        }\\n      }\\n    };\\n    function HistoryController() {\\n        this.historyBuffer = [];\\n        this.iterator = 0;\\n        this.initialPrefix = null;\\n    }\\n    HistoryController.prototype = {\\n      // the input argument here acts a user entered prefix for a small time\\n      // until we start autocompletion in which case it is the autocompleted.\\n      nextMatch: function (input, up) {\\n        var historyBuffer = this.historyBuffer;\\n        var dir = up ? -1 : 1;\\n        if (this.initialPrefix === null) this.initialPrefix = input;\\n        for (var i = this.iterator + dir; up ? i >= 0 : i < historyBuffer.length; i+= dir) {\\n          var element = historyBuffer[i];\\n          for (var j = 0; j <= element.length; j++) {\\n            if (this.initialPrefix == element.substring(0, j)) {\\n              this.iterator = i;\\n              return element;\\n            }\\n          }\\n        }\\n        // should return the user input in case we reach the end of buffer.\\n        if (i >= historyBuffer.length) {\\n          this.iterator = historyBuffer.length;\\n          return this.initialPrefix;\\n        }\\n        // return the last autocompleted query or exCommand as it is.\\n        if (i < 0 ) return input;\\n      },\\n      pushInput: function(input) {\\n        var index = this.historyBuffer.indexOf(input);\\n        if (index > -1) this.historyBuffer.splice(index, 1);\\n        if (input.length) this.historyBuffer.push(input);\\n      },\\n      reset: function() {\\n        this.initialPrefix = null;\\n        this.iterator = this.historyBuffer.length;\\n      }\\n    };\\n    var commandDispatcher = {\\n      matchCommand: function(keys, keyMap, inputState, context) {\\n        var matches = commandMatches(keys, keyMap, context, inputState);\\n        if (!matches.full && !matches.partial) {\\n          return {type: 'none'};\\n        } else if (!matches.full && matches.partial) {\\n          return {type: 'partial'};\\n        }\\n\\n        var bestMatch;\\n        for (var i = 0; i < matches.full.length; i++) {\\n          var match = matches.full[i];\\n          if (!bestMatch) {\\n            bestMatch = match;\\n          }\\n        }\\n        if (bestMatch.keys.slice(-11) == '<character>') {\\n          var character = lastChar(keys);\\n          if (!character) return {type: 'none'};\\n          inputState.selectedCharacter = character;\\n        }\\n        return {type: 'full', command: bestMatch};\\n      },\\n      processCommand: function(cm, vim, command) {\\n        vim.inputState.repeatOverride = command.repeatOverride;\\n        switch (command.type) {\\n          case 'motion':\\n            this.processMotion(cm, vim, command);\\n            break;\\n          case 'operator':\\n            this.processOperator(cm, vim, command);\\n            break;\\n          case 'operatorMotion':\\n            this.processOperatorMotion(cm, vim, command);\\n            break;\\n          case 'action':\\n            this.processAction(cm, vim, command);\\n            break;\\n          case 'search':\\n            this.processSearch(cm, vim, command);\\n            break;\\n          case 'ex':\\n          case 'keyToEx':\\n            this.processEx(cm, vim, command);\\n            break;\\n          default:\\n            break;\\n        }\\n      },\\n      processMotion: function(cm, vim, command) {\\n        vim.inputState.motion = command.motion;\\n        vim.inputState.motionArgs = copyArgs(command.motionArgs);\\n        this.evalInput(cm, vim);\\n      },\\n      processOperator: function(cm, vim, command) {\\n        var inputState = vim.inputState;\\n        if (inputState.operator) {\\n          if (inputState.operator == command.operator) {\\n            // Typing an operator twice like 'dd' makes the operator operate\\n            // linewise\\n            inputState.motion = 'expandToLine';\\n            inputState.motionArgs = { linewise: true };\\n            this.evalInput(cm, vim);\\n            return;\\n          } else {\\n            // 2 different operators in a row doesn't make sense.\\n            clearInputState(cm);\\n          }\\n        }\\n        inputState.operator = command.operator;\\n        inputState.operatorArgs = copyArgs(command.operatorArgs);\\n        if (command.exitVisualBlock) {\\n            vim.visualBlock = false;\\n            updateCmSelection(cm);\\n        }\\n        if (vim.visualMode) {\\n          // Operating on a selection in visual mode. We don't need a motion.\\n          this.evalInput(cm, vim);\\n        }\\n      },\\n      processOperatorMotion: function(cm, vim, command) {\\n        var visualMode = vim.visualMode;\\n        var operatorMotionArgs = copyArgs(command.operatorMotionArgs);\\n        if (operatorMotionArgs) {\\n          // Operator motions may have special behavior in visual mode.\\n          if (visualMode && operatorMotionArgs.visualLine) {\\n            vim.visualLine = true;\\n          }\\n        }\\n        this.processOperator(cm, vim, command);\\n        if (!visualMode) {\\n          this.processMotion(cm, vim, command);\\n        }\\n      },\\n      processAction: function(cm, vim, command) {\\n        var inputState = vim.inputState;\\n        var repeat = inputState.getRepeat();\\n        var repeatIsExplicit = !!repeat;\\n        var actionArgs = copyArgs(command.actionArgs) || {};\\n        if (inputState.selectedCharacter) {\\n          actionArgs.selectedCharacter = inputState.selectedCharacter;\\n        }\\n        // Actions may or may not have motions and operators. Do these first.\\n        if (command.operator) {\\n          this.processOperator(cm, vim, command);\\n        }\\n        if (command.motion) {\\n          this.processMotion(cm, vim, command);\\n        }\\n        if (command.motion || command.operator) {\\n          this.evalInput(cm, vim);\\n        }\\n        actionArgs.repeat = repeat || 1;\\n        actionArgs.repeatIsExplicit = repeatIsExplicit;\\n        actionArgs.registerName = inputState.registerName;\\n        clearInputState(cm);\\n        vim.lastMotion = null;\\n        if (command.isEdit) {\\n          this.recordLastEdit(vim, inputState, command);\\n        }\\n        actions[command.action](cm, actionArgs, vim);\\n      },\\n      processSearch: function(cm, vim, command) {\\n        if (!cm.getSearchCursor) {\\n          // Search depends on SearchCursor.\\n          return;\\n        }\\n        var forward = command.searchArgs.forward;\\n        var wholeWordOnly = command.searchArgs.wholeWordOnly;\\n        getSearchState(cm).setReversed(!forward);\\n        var promptPrefix = (forward) ? '/' : '?';\\n        var originalQuery = getSearchState(cm).getQuery();\\n        var originalScrollPos = cm.getScrollInfo();\\n        function handleQuery(query, ignoreCase, smartCase) {\\n          vimGlobalState.searchHistoryController.pushInput(query);\\n          vimGlobalState.searchHistoryController.reset();\\n          try {\\n            updateSearchQuery(cm, query, ignoreCase, smartCase);\\n          } catch (e) {\\n            showConfirm(cm, 'Invalid regex: ' + query);\\n            clearInputState(cm);\\n            return;\\n          }\\n          commandDispatcher.processMotion(cm, vim, {\\n            type: 'motion',\\n            motion: 'findNext',\\n            motionArgs: { forward: true, toJumplist: command.searchArgs.toJumplist }\\n          });\\n        }\\n        function onPromptClose(query) {\\n          cm.scrollTo(originalScrollPos.left, originalScrollPos.top);\\n          handleQuery(query, true /** ignoreCase */, true /** smartCase */);\\n          var macroModeState = vimGlobalState.macroModeState;\\n          if (macroModeState.isRecording) {\\n            logSearchQuery(macroModeState, query);\\n          }\\n        }\\n        function onPromptKeyUp(e, query, close) {\\n          var keyName = CodeMirror.keyName(e), up, offset;\\n          if (keyName == 'Up' || keyName == 'Down') {\\n            up = keyName == 'Up' ? true : false;\\n            offset = e.target ? e.target.selectionEnd : 0;\\n            query = vimGlobalState.searchHistoryController.nextMatch(query, up) || '';\\n            close(query);\\n            if (offset && e.target) e.target.selectionEnd = e.target.selectionStart = Math.min(offset, e.target.value.length);\\n          } else {\\n            if ( keyName != 'Left' && keyName != 'Right' && keyName != 'Ctrl' && keyName != 'Alt' && keyName != 'Shift')\\n              vimGlobalState.searchHistoryController.reset();\\n          }\\n          var parsedQuery;\\n          try {\\n            parsedQuery = updateSearchQuery(cm, query,\\n                true /** ignoreCase */, true /** smartCase */);\\n          } catch (e) {\\n            // Swallow bad regexes for incremental search.\\n          }\\n          if (parsedQuery) {\\n            cm.scrollIntoView(findNext(cm, !forward, parsedQuery), 30);\\n          } else {\\n            clearSearchHighlight(cm);\\n            cm.scrollTo(originalScrollPos.left, originalScrollPos.top);\\n          }\\n        }\\n        function onPromptKeyDown(e, query, close) {\\n          var keyName = CodeMirror.keyName(e);\\n          if (keyName == 'Esc' || keyName == 'Ctrl-C' || keyName == 'Ctrl-[' ||\\n              (keyName == 'Backspace' && query == '')) {\\n            vimGlobalState.searchHistoryController.pushInput(query);\\n            vimGlobalState.searchHistoryController.reset();\\n            updateSearchQuery(cm, originalQuery);\\n            clearSearchHighlight(cm);\\n            cm.scrollTo(originalScrollPos.left, originalScrollPos.top);\\n            CodeMirror.e_stop(e);\\n            clearInputState(cm);\\n            close();\\n            cm.focus();\\n          } else if (keyName == 'Up' || keyName == 'Down') {\\n            CodeMirror.e_stop(e);\\n          } else if (keyName == 'Ctrl-U') {\\n            // Ctrl-U clears input.\\n            CodeMirror.e_stop(e);\\n            close('');\\n          }\\n        }\\n        switch (command.searchArgs.querySrc) {\\n          case 'prompt':\\n            var macroModeState = vimGlobalState.macroModeState;\\n            if (macroModeState.isPlaying) {\\n              var query = macroModeState.replaySearchQueries.shift();\\n              handleQuery(query, true /** ignoreCase */, false /** smartCase */);\\n            } else {\\n              showPrompt(cm, {\\n                  onClose: onPromptClose,\\n                  prefix: promptPrefix,\\n                  desc: searchPromptDesc,\\n                  onKeyUp: onPromptKeyUp,\\n                  onKeyDown: onPromptKeyDown\\n              });\\n            }\\n            break;\\n          case 'wordUnderCursor':\\n            var word = expandWordUnderCursor(cm, false /** inclusive */,\\n                true /** forward */, false /** bigWord */,\\n                true /** noSymbol */);\\n            var isKeyword = true;\\n            if (!word) {\\n              word = expandWordUnderCursor(cm, false /** inclusive */,\\n                  true /** forward */, false /** bigWord */,\\n                  false /** noSymbol */);\\n              isKeyword = false;\\n            }\\n            if (!word) {\\n              return;\\n            }\\n            var query = cm.getLine(word.start.line).substring(word.start.ch,\\n                word.end.ch);\\n            if (isKeyword && wholeWordOnly) {\\n                query = '\\\\\\\\b' + query + '\\\\\\\\b';\\n            } else {\\n              query = escapeRegex(query);\\n            }\\n\\n            // cachedCursor is used to save the old position of the cursor\\n            // when * or # causes vim to seek for the nearest word and shift\\n            // the cursor before entering the motion.\\n            vimGlobalState.jumpList.cachedCursor = cm.getCursor();\\n            cm.setCursor(word.start);\\n\\n            handleQuery(query, true /** ignoreCase */, false /** smartCase */);\\n            break;\\n        }\\n      },\\n      processEx: function(cm, vim, command) {\\n        function onPromptClose(input) {\\n          // Give the prompt some time to close so that if processCommand shows\\n          // an error, the elements don't overlap.\\n          vimGlobalState.exCommandHistoryController.pushInput(input);\\n          vimGlobalState.exCommandHistoryController.reset();\\n          exCommandDispatcher.processCommand(cm, input);\\n        }\\n        function onPromptKeyDown(e, input, close) {\\n          var keyName = CodeMirror.keyName(e), up, offset;\\n          if (keyName == 'Esc' || keyName == 'Ctrl-C' || keyName == 'Ctrl-[' ||\\n              (keyName == 'Backspace' && input == '')) {\\n            vimGlobalState.exCommandHistoryController.pushInput(input);\\n            vimGlobalState.exCommandHistoryController.reset();\\n            CodeMirror.e_stop(e);\\n            clearInputState(cm);\\n            close();\\n            cm.focus();\\n          }\\n          if (keyName == 'Up' || keyName == 'Down') {\\n            CodeMirror.e_stop(e);\\n            up = keyName == 'Up' ? true : false;\\n            offset = e.target ? e.target.selectionEnd : 0;\\n            input = vimGlobalState.exCommandHistoryController.nextMatch(input, up) || '';\\n            close(input);\\n            if (offset && e.target) e.target.selectionEnd = e.target.selectionStart = Math.min(offset, e.target.value.length);\\n          } else if (keyName == 'Ctrl-U') {\\n            // Ctrl-U clears input.\\n            CodeMirror.e_stop(e);\\n            close('');\\n          } else {\\n            if ( keyName != 'Left' && keyName != 'Right' && keyName != 'Ctrl' && keyName != 'Alt' && keyName != 'Shift')\\n              vimGlobalState.exCommandHistoryController.reset();\\n          }\\n        }\\n        if (command.type == 'keyToEx') {\\n          // Handle user defined Ex to Ex mappings\\n          exCommandDispatcher.processCommand(cm, command.exArgs.input);\\n        } else {\\n          if (vim.visualMode) {\\n            showPrompt(cm, { onClose: onPromptClose, prefix: ':', value: '\\\\'<,\\\\'>',\\n                onKeyDown: onPromptKeyDown, selectValueOnOpen: false});\\n          } else {\\n            showPrompt(cm, { onClose: onPromptClose, prefix: ':',\\n                onKeyDown: onPromptKeyDown});\\n          }\\n        }\\n      },\\n      evalInput: function(cm, vim) {\\n        // If the motion command is set, execute both the operator and motion.\\n        // Otherwise return.\\n        var inputState = vim.inputState;\\n        var motion = inputState.motion;\\n        var motionArgs = inputState.motionArgs || {};\\n        var operator = inputState.operator;\\n        var operatorArgs = inputState.operatorArgs || {};\\n        var registerName = inputState.registerName;\\n        var sel = vim.sel;\\n        // TODO: Make sure cm and vim selections are identical outside visual mode.\\n        var origHead = copyCursor(vim.visualMode ? clipCursorToContent(cm, sel.head): cm.getCursor('head'));\\n        var origAnchor = copyCursor(vim.visualMode ? clipCursorToContent(cm, sel.anchor) : cm.getCursor('anchor'));\\n        var oldHead = copyCursor(origHead);\\n        var oldAnchor = copyCursor(origAnchor);\\n        var newHead, newAnchor;\\n        var repeat;\\n        if (operator) {\\n          this.recordLastEdit(vim, inputState);\\n        }\\n        if (inputState.repeatOverride !== undefined) {\\n          // If repeatOverride is specified, that takes precedence over the\\n          // input state's repeat. Used by Ex mode and can be user defined.\\n          repeat = inputState.repeatOverride;\\n        } else {\\n          repeat = inputState.getRepeat();\\n        }\\n        if (repeat > 0 && motionArgs.explicitRepeat) {\\n          motionArgs.repeatIsExplicit = true;\\n        } else if (motionArgs.noRepeat ||\\n            (!motionArgs.explicitRepeat && repeat === 0)) {\\n          repeat = 1;\\n          motionArgs.repeatIsExplicit = false;\\n        }\\n        if (inputState.selectedCharacter) {\\n          // If there is a character input, stick it in all of the arg arrays.\\n          motionArgs.selectedCharacter = operatorArgs.selectedCharacter =\\n              inputState.selectedCharacter;\\n        }\\n        motionArgs.repeat = repeat;\\n        clearInputState(cm);\\n        if (motion) {\\n          var motionResult = motions[motion](cm, origHead, motionArgs, vim);\\n          vim.lastMotion = motions[motion];\\n          if (!motionResult) {\\n            return;\\n          }\\n          if (motionArgs.toJumplist) {\\n            var jumpList = vimGlobalState.jumpList;\\n            // if the current motion is # or *, use cachedCursor\\n            var cachedCursor = jumpList.cachedCursor;\\n            if (cachedCursor) {\\n              recordJumpPosition(cm, cachedCursor, motionResult);\\n              delete jumpList.cachedCursor;\\n            } else {\\n              recordJumpPosition(cm, origHead, motionResult);\\n            }\\n          }\\n          if (motionResult instanceof Array) {\\n            newAnchor = motionResult[0];\\n            newHead = motionResult[1];\\n          } else {\\n            newHead = motionResult;\\n          }\\n          // TODO: Handle null returns from motion commands better.\\n          if (!newHead) {\\n            newHead = copyCursor(origHead);\\n          }\\n          if (vim.visualMode) {\\n            if (!(vim.visualBlock && newHead.ch === Infinity)) {\\n              newHead = clipCursorToContent(cm, newHead);\\n            }\\n            if (newAnchor) {\\n              newAnchor = clipCursorToContent(cm, newAnchor);\\n            }\\n            newAnchor = newAnchor || oldAnchor;\\n            sel.anchor = newAnchor;\\n            sel.head = newHead;\\n            updateCmSelection(cm);\\n            updateMark(cm, vim, '<',\\n                cursorIsBefore(newAnchor, newHead) ? newAnchor\\n                    : newHead);\\n            updateMark(cm, vim, '>',\\n                cursorIsBefore(newAnchor, newHead) ? newHead\\n                    : newAnchor);\\n          } else if (!operator) {\\n            newHead = clipCursorToContent(cm, newHead);\\n            cm.setCursor(newHead.line, newHead.ch);\\n          }\\n        }\\n        if (operator) {\\n          if (operatorArgs.lastSel) {\\n            // Replaying a visual mode operation\\n            newAnchor = oldAnchor;\\n            var lastSel = operatorArgs.lastSel;\\n            var lineOffset = Math.abs(lastSel.head.line - lastSel.anchor.line);\\n            var chOffset = Math.abs(lastSel.head.ch - lastSel.anchor.ch);\\n            if (lastSel.visualLine) {\\n              // Linewise Visual mode: The same number of lines.\\n              newHead = Pos(oldAnchor.line + lineOffset, oldAnchor.ch);\\n            } else if (lastSel.visualBlock) {\\n              // Blockwise Visual mode: The same number of lines and columns.\\n              newHead = Pos(oldAnchor.line + lineOffset, oldAnchor.ch + chOffset);\\n            } else if (lastSel.head.line == lastSel.anchor.line) {\\n              // Normal Visual mode within one line: The same number of characters.\\n              newHead = Pos(oldAnchor.line, oldAnchor.ch + chOffset);\\n            } else {\\n              // Normal Visual mode with several lines: The same number of lines, in the\\n              // last line the same number of characters as in the last line the last time.\\n              newHead = Pos(oldAnchor.line + lineOffset, oldAnchor.ch);\\n            }\\n            vim.visualMode = true;\\n            vim.visualLine = lastSel.visualLine;\\n            vim.visualBlock = lastSel.visualBlock;\\n            sel = vim.sel = {\\n              anchor: newAnchor,\\n              head: newHead\\n            };\\n            updateCmSelection(cm);\\n          } else if (vim.visualMode) {\\n            operatorArgs.lastSel = {\\n              anchor: copyCursor(sel.anchor),\\n              head: copyCursor(sel.head),\\n              visualBlock: vim.visualBlock,\\n              visualLine: vim.visualLine\\n            };\\n          }\\n          var curStart, curEnd, linewise, mode;\\n          var cmSel;\\n          if (vim.visualMode) {\\n            // Init visual op\\n            curStart = cursorMin(sel.head, sel.anchor);\\n            curEnd = cursorMax(sel.head, sel.anchor);\\n            linewise = vim.visualLine || operatorArgs.linewise;\\n            mode = vim.visualBlock ? 'block' :\\n                   linewise ? 'line' :\\n                   'char';\\n            cmSel = makeCmSelection(cm, {\\n              anchor: curStart,\\n              head: curEnd\\n            }, mode);\\n            if (linewise) {\\n              var ranges = cmSel.ranges;\\n              if (mode == 'block') {\\n                // Linewise operators in visual block mode extend to end of line\\n                for (var i = 0; i < ranges.length; i++) {\\n                  ranges[i].head.ch = lineLength(cm, ranges[i].head.line);\\n                }\\n              } else if (mode == 'line') {\\n                ranges[0].head = Pos(ranges[0].head.line + 1, 0);\\n              }\\n            }\\n          } else {\\n            // Init motion op\\n            curStart = copyCursor(newAnchor || oldAnchor);\\n            curEnd = copyCursor(newHead || oldHead);\\n            if (cursorIsBefore(curEnd, curStart)) {\\n              var tmp = curStart;\\n              curStart = curEnd;\\n              curEnd = tmp;\\n            }\\n            linewise = motionArgs.linewise || operatorArgs.linewise;\\n            if (linewise) {\\n              // Expand selection to entire line.\\n              expandSelectionToLine(cm, curStart, curEnd);\\n            } else if (motionArgs.forward) {\\n              // Clip to trailing newlines only if the motion goes forward.\\n              clipToLine(cm, curStart, curEnd);\\n            }\\n            mode = 'char';\\n            var exclusive = !motionArgs.inclusive || linewise;\\n            cmSel = makeCmSelection(cm, {\\n              anchor: curStart,\\n              head: curEnd\\n            }, mode, exclusive);\\n          }\\n          cm.setSelections(cmSel.ranges, cmSel.primary);\\n          vim.lastMotion = null;\\n          operatorArgs.repeat = repeat; // For indent in visual mode.\\n          operatorArgs.registerName = registerName;\\n          // Keep track of linewise as it affects how paste and change behave.\\n          operatorArgs.linewise = linewise;\\n          var operatorMoveTo = operators[operator](\\n            cm, operatorArgs, cmSel.ranges, oldAnchor, newHead);\\n          if (vim.visualMode) {\\n            exitVisualMode(cm, operatorMoveTo != null);\\n          }\\n          if (operatorMoveTo) {\\n            cm.setCursor(operatorMoveTo);\\n          }\\n        }\\n      },\\n      recordLastEdit: function(vim, inputState, actionCommand) {\\n        var macroModeState = vimGlobalState.macroModeState;\\n        if (macroModeState.isPlaying) { return; }\\n        vim.lastEditInputState = inputState;\\n        vim.lastEditActionCommand = actionCommand;\\n        macroModeState.lastInsertModeChanges.changes = [];\\n        macroModeState.lastInsertModeChanges.expectCursorActivityForChange = false;\\n        macroModeState.lastInsertModeChanges.visualBlock = vim.visualBlock ? vim.sel.head.line - vim.sel.anchor.line : 0;\\n      }\\n    };\\n\\n    /**\\n     * typedef {Object{line:number,ch:number}} Cursor An object containing the\\n     *     position of the cursor.\\n     */\\n    // All of the functions below return Cursor objects.\\n    var motions = {\\n      moveToTopLine: function(cm, _head, motionArgs) {\\n        var line = getUserVisibleLines(cm).top + motionArgs.repeat -1;\\n        return Pos(line, findFirstNonWhiteSpaceCharacter(cm.getLine(line)));\\n      },\\n      moveToMiddleLine: function(cm) {\\n        var range = getUserVisibleLines(cm);\\n        var line = Math.floor((range.top + range.bottom) * 0.5);\\n        return Pos(line, findFirstNonWhiteSpaceCharacter(cm.getLine(line)));\\n      },\\n      moveToBottomLine: function(cm, _head, motionArgs) {\\n        var line = getUserVisibleLines(cm).bottom - motionArgs.repeat +1;\\n        return Pos(line, findFirstNonWhiteSpaceCharacter(cm.getLine(line)));\\n      },\\n      expandToLine: function(_cm, head, motionArgs) {\\n        // Expands forward to end of line, and then to next line if repeat is\\n        // >1. Does not handle backward motion!\\n        var cur = head;\\n        return Pos(cur.line + motionArgs.repeat - 1, Infinity);\\n      },\\n      findNext: function(cm, _head, motionArgs) {\\n        var state = getSearchState(cm);\\n        var query = state.getQuery();\\n        if (!query) {\\n          return;\\n        }\\n        var prev = !motionArgs.forward;\\n        // If search is initiated with ? instead of /, negate direction.\\n        prev = (state.isReversed()) ? !prev : prev;\\n        highlightSearchMatches(cm, query);\\n        return findNext(cm, prev/** prev */, query, motionArgs.repeat);\\n      },\\n      goToMark: function(cm, _head, motionArgs, vim) {\\n        var pos = getMarkPos(cm, vim, motionArgs.selectedCharacter);\\n        if (pos) {\\n          return motionArgs.linewise ? { line: pos.line, ch: findFirstNonWhiteSpaceCharacter(cm.getLine(pos.line)) } : pos;\\n        }\\n        return null;\\n      },\\n      moveToOtherHighlightedEnd: function(cm, _head, motionArgs, vim) {\\n        if (vim.visualBlock && motionArgs.sameLine) {\\n          var sel = vim.sel;\\n          return [\\n            clipCursorToContent(cm, Pos(sel.anchor.line, sel.head.ch)),\\n            clipCursorToContent(cm, Pos(sel.head.line, sel.anchor.ch))\\n          ];\\n        } else {\\n          return ([vim.sel.head, vim.sel.anchor]);\\n        }\\n      },\\n      jumpToMark: function(cm, head, motionArgs, vim) {\\n        var best = head;\\n        for (var i = 0; i < motionArgs.repeat; i++) {\\n          var cursor = best;\\n          for (var key in vim.marks) {\\n            if (!isLowerCase(key)) {\\n              continue;\\n            }\\n            var mark = vim.marks[key].find();\\n            var isWrongDirection = (motionArgs.forward) ?\\n              cursorIsBefore(mark, cursor) : cursorIsBefore(cursor, mark);\\n\\n            if (isWrongDirection) {\\n              continue;\\n            }\\n            if (motionArgs.linewise && (mark.line == cursor.line)) {\\n              continue;\\n            }\\n\\n            var equal = cursorEqual(cursor, best);\\n            var between = (motionArgs.forward) ?\\n              cursorIsBetween(cursor, mark, best) :\\n              cursorIsBetween(best, mark, cursor);\\n\\n            if (equal || between) {\\n              best = mark;\\n            }\\n          }\\n        }\\n\\n        if (motionArgs.linewise) {\\n          // Vim places the cursor on the first non-whitespace character of\\n          // the line if there is one, else it places the cursor at the end\\n          // of the line, regardless of whether a mark was found.\\n          best = Pos(best.line, findFirstNonWhiteSpaceCharacter(cm.getLine(best.line)));\\n        }\\n        return best;\\n      },\\n      moveByCharacters: function(_cm, head, motionArgs) {\\n        var cur = head;\\n        var repeat = motionArgs.repeat;\\n        var ch = motionArgs.forward ? cur.ch + repeat : cur.ch - repeat;\\n        return Pos(cur.line, ch);\\n      },\\n      moveByLines: function(cm, head, motionArgs, vim) {\\n        var cur = head;\\n        var endCh = cur.ch;\\n        // Depending what our last motion was, we may want to do different\\n        // things. If our last motion was moving vertically, we want to\\n        // preserve the HPos from our last horizontal move.  If our last motion\\n        // was going to the end of a line, moving vertically we should go to\\n        // the end of the line, etc.\\n        switch (vim.lastMotion) {\\n          case this.moveByLines:\\n          case this.moveByDisplayLines:\\n          case this.moveByScroll:\\n          case this.moveToColumn:\\n          case this.moveToEol:\\n            endCh = vim.lastHPos;\\n            break;\\n          default:\\n            vim.lastHPos = endCh;\\n        }\\n        var repeat = motionArgs.repeat+(motionArgs.repeatOffset||0);\\n        var line = motionArgs.forward ? cur.line + repeat : cur.line - repeat;\\n        var first = cm.firstLine();\\n        var last = cm.lastLine();\\n        var posV = cm.findPosV(cur, (motionArgs.forward ? repeat : -repeat), 'line', vim.lastHSPos);\\n        var hasMarkedText = motionArgs.forward ? posV.line > line : posV.line < line;\\n        if (hasMarkedText) {\\n          line = posV.line;\\n          endCh = posV.ch;\\n        }\\n        // Vim go to line begin or line end when cursor at first/last line and\\n        // move to previous/next line is triggered.\\n        if (line < first && cur.line == first){\\n          return this.moveToStartOfLine(cm, head, motionArgs, vim);\\n        }else if (line > last && cur.line == last){\\n            return this.moveToEol(cm, head, motionArgs, vim, true);\\n        }\\n        if (motionArgs.toFirstChar){\\n          endCh=findFirstNonWhiteSpaceCharacter(cm.getLine(line));\\n          vim.lastHPos = endCh;\\n        }\\n        vim.lastHSPos = cm.charCoords(Pos(line, endCh),'div').left;\\n        return Pos(line, endCh);\\n      },\\n      moveByDisplayLines: function(cm, head, motionArgs, vim) {\\n        var cur = head;\\n        switch (vim.lastMotion) {\\n          case this.moveByDisplayLines:\\n          case this.moveByScroll:\\n          case this.moveByLines:\\n          case this.moveToColumn:\\n          case this.moveToEol:\\n            break;\\n          default:\\n            vim.lastHSPos = cm.charCoords(cur,'div').left;\\n        }\\n        var repeat = motionArgs.repeat;\\n        var res=cm.findPosV(cur,(motionArgs.forward ? repeat : -repeat),'line',vim.lastHSPos);\\n        if (res.hitSide) {\\n          if (motionArgs.forward) {\\n            var lastCharCoords = cm.charCoords(res, 'div');\\n            var goalCoords = { top: lastCharCoords.top + 8, left: vim.lastHSPos };\\n            var res = cm.coordsChar(goalCoords, 'div');\\n          } else {\\n            var resCoords = cm.charCoords(Pos(cm.firstLine(), 0), 'div');\\n            resCoords.left = vim.lastHSPos;\\n            res = cm.coordsChar(resCoords, 'div');\\n          }\\n        }\\n        vim.lastHPos = res.ch;\\n        return res;\\n      },\\n      moveByPage: function(cm, head, motionArgs) {\\n        // CodeMirror only exposes functions that move the cursor page down, so\\n        // doing this bad hack to move the cursor and move it back. evalInput\\n        // will move the cursor to where it should be in the end.\\n        var curStart = head;\\n        var repeat = motionArgs.repeat;\\n        return cm.findPosV(curStart, (motionArgs.forward ? repeat : -repeat), 'page');\\n      },\\n      moveByParagraph: function(cm, head, motionArgs) {\\n        var dir = motionArgs.forward ? 1 : -1;\\n        return findParagraph(cm, head, motionArgs.repeat, dir);\\n      },\\n      moveBySentence: function(cm, head, motionArgs) {\\n        var dir = motionArgs.forward ? 1 : -1;\\n        return findSentence(cm, head, motionArgs.repeat, dir);\\n      },\\n      moveByScroll: function(cm, head, motionArgs, vim) {\\n        var scrollbox = cm.getScrollInfo();\\n        var curEnd = null;\\n        var repeat = motionArgs.repeat;\\n        if (!repeat) {\\n          repeat = scrollbox.clientHeight / (2 * cm.defaultTextHeight());\\n        }\\n        var orig = cm.charCoords(head, 'local');\\n        motionArgs.repeat = repeat;\\n        var curEnd = motions.moveByDisplayLines(cm, head, motionArgs, vim);\\n        if (!curEnd) {\\n          return null;\\n        }\\n        var dest = cm.charCoords(curEnd, 'local');\\n        cm.scrollTo(null, scrollbox.top + dest.top - orig.top);\\n        return curEnd;\\n      },\\n      moveByWords: function(cm, head, motionArgs) {\\n        return moveToWord(cm, head, motionArgs.repeat, !!motionArgs.forward,\\n            !!motionArgs.wordEnd, !!motionArgs.bigWord);\\n      },\\n      moveTillCharacter: function(cm, _head, motionArgs) {\\n        var repeat = motionArgs.repeat;\\n        var curEnd = moveToCharacter(cm, repeat, motionArgs.forward,\\n            motionArgs.selectedCharacter);\\n        var increment = motionArgs.forward ? -1 : 1;\\n        recordLastCharacterSearch(increment, motionArgs);\\n        if (!curEnd) return null;\\n        curEnd.ch += increment;\\n        return curEnd;\\n      },\\n      moveToCharacter: function(cm, head, motionArgs) {\\n        var repeat = motionArgs.repeat;\\n        recordLastCharacterSearch(0, motionArgs);\\n        return moveToCharacter(cm, repeat, motionArgs.forward,\\n            motionArgs.selectedCharacter) || head;\\n      },\\n      moveToSymbol: function(cm, head, motionArgs) {\\n        var repeat = motionArgs.repeat;\\n        return findSymbol(cm, repeat, motionArgs.forward,\\n            motionArgs.selectedCharacter) || head;\\n      },\\n      moveToColumn: function(cm, head, motionArgs, vim) {\\n        var repeat = motionArgs.repeat;\\n        // repeat is equivalent to which column we want to move to!\\n        vim.lastHPos = repeat - 1;\\n        vim.lastHSPos = cm.charCoords(head,'div').left;\\n        return moveToColumn(cm, repeat);\\n      },\\n      moveToEol: function(cm, head, motionArgs, vim, keepHPos) {\\n        var cur = head;\\n        var retval= Pos(cur.line + motionArgs.repeat - 1, Infinity);\\n        var end=cm.clipPos(retval);\\n        end.ch--;\\n        if (!keepHPos) {\\n          vim.lastHPos = Infinity;\\n          vim.lastHSPos = cm.charCoords(end,'div').left;\\n        }\\n        return retval;\\n      },\\n      moveToFirstNonWhiteSpaceCharacter: function(cm, head) {\\n        // Go to the start of the line where the text begins, or the end for\\n        // whitespace-only lines\\n        var cursor = head;\\n        return Pos(cursor.line,\\n                   findFirstNonWhiteSpaceCharacter(cm.getLine(cursor.line)));\\n      },\\n      moveToMatchedSymbol: function(cm, head) {\\n        var cursor = head;\\n        var line = cursor.line;\\n        var ch = cursor.ch;\\n        var lineText = cm.getLine(line);\\n        var symbol;\\n        for (; ch < lineText.length; ch++) {\\n          symbol = lineText.charAt(ch);\\n          if (symbol && isMatchableSymbol(symbol)) {\\n            var style = cm.getTokenTypeAt(Pos(line, ch + 1));\\n            if (style !== \\\"string\\\" && style !== \\\"comment\\\") {\\n              break;\\n            }\\n          }\\n        }\\n        if (ch < lineText.length) {\\n          // Only include angle brackets in analysis if they are being matched.\\n          var re = (ch === '<' || ch === '>') ? /[(){}[\\\\]<>]/ : /[(){}[\\\\]]/;\\n          var matched = cm.findMatchingBracket(Pos(line, ch), {bracketRegex: re});\\n          return matched.to;\\n        } else {\\n          return cursor;\\n        }\\n      },\\n      moveToStartOfLine: function(_cm, head) {\\n        return Pos(head.line, 0);\\n      },\\n      moveToLineOrEdgeOfDocument: function(cm, _head, motionArgs) {\\n        var lineNum = motionArgs.forward ? cm.lastLine() : cm.firstLine();\\n        if (motionArgs.repeatIsExplicit) {\\n          lineNum = motionArgs.repeat - cm.getOption('firstLineNumber');\\n        }\\n        return Pos(lineNum,\\n                   findFirstNonWhiteSpaceCharacter(cm.getLine(lineNum)));\\n      },\\n      textObjectManipulation: function(cm, head, motionArgs, vim) {\\n        // TODO: lots of possible exceptions that can be thrown here. Try da(\\n        //     outside of a () block.\\n        var mirroredPairs = {'(': ')', ')': '(',\\n                             '{': '}', '}': '{',\\n                             '[': ']', ']': '[',\\n                             '<': '>', '>': '<'};\\n        var selfPaired = {'\\\\'': true, '\\\"': true, '`': true};\\n\\n        var character = motionArgs.selectedCharacter;\\n        // 'b' refers to  '()' block.\\n        // 'B' refers to  '{}' block.\\n        if (character == 'b') {\\n          character = '(';\\n        } else if (character == 'B') {\\n          character = '{';\\n        }\\n\\n        // Inclusive is the difference between a and i\\n        // TODO: Instead of using the additional text object map to perform text\\n        //     object operations, merge the map into the defaultKeyMap and use\\n        //     motionArgs to define behavior. Define separate entries for 'aw',\\n        //     'iw', 'a[', 'i[', etc.\\n        var inclusive = !motionArgs.textObjectInner;\\n\\n        var tmp;\\n        if (mirroredPairs[character]) {\\n          tmp = selectCompanionObject(cm, head, character, inclusive);\\n        } else if (selfPaired[character]) {\\n          tmp = findBeginningAndEnd(cm, head, character, inclusive);\\n        } else if (character === 'W') {\\n          tmp = expandWordUnderCursor(cm, inclusive, true /** forward */,\\n                                                     true /** bigWord */);\\n        } else if (character === 'w') {\\n          tmp = expandWordUnderCursor(cm, inclusive, true /** forward */,\\n                                                     false /** bigWord */);\\n        } else if (character === 'p') {\\n          tmp = findParagraph(cm, head, motionArgs.repeat, 0, inclusive);\\n          motionArgs.linewise = true;\\n          if (vim.visualMode) {\\n            if (!vim.visualLine) { vim.visualLine = true; }\\n          } else {\\n            var operatorArgs = vim.inputState.operatorArgs;\\n            if (operatorArgs) { operatorArgs.linewise = true; }\\n            tmp.end.line--;\\n          }\\n        } else {\\n          // No text object defined for this, don't move.\\n          return null;\\n        }\\n\\n        if (!cm.state.vim.visualMode) {\\n          return [tmp.start, tmp.end];\\n        } else {\\n          return expandSelection(cm, tmp.start, tmp.end);\\n        }\\n      },\\n\\n      repeatLastCharacterSearch: function(cm, head, motionArgs) {\\n        var lastSearch = vimGlobalState.lastCharacterSearch;\\n        var repeat = motionArgs.repeat;\\n        var forward = motionArgs.forward === lastSearch.forward;\\n        var increment = (lastSearch.increment ? 1 : 0) * (forward ? -1 : 1);\\n        cm.moveH(-increment, 'char');\\n        motionArgs.inclusive = forward ? true : false;\\n        var curEnd = moveToCharacter(cm, repeat, forward, lastSearch.selectedCharacter);\\n        if (!curEnd) {\\n          cm.moveH(increment, 'char');\\n          return head;\\n        }\\n        curEnd.ch += increment;\\n        return curEnd;\\n      }\\n    };\\n\\n    function defineMotion(name, fn) {\\n      motions[name] = fn;\\n    }\\n\\n    function fillArray(val, times) {\\n      var arr = [];\\n      for (var i = 0; i < times; i++) {\\n        arr.push(val);\\n      }\\n      return arr;\\n    }\\n    /**\\n     * An operator acts on a text selection. It receives the list of selections\\n     * as input. The corresponding CodeMirror selection is guaranteed to\\n    * match the input selection.\\n     */\\n    var operators = {\\n      change: function(cm, args, ranges) {\\n        var finalHead, text;\\n        var vim = cm.state.vim;\\n        var anchor = ranges[0].anchor,\\n            head = ranges[0].head;\\n        if (!vim.visualMode) {\\n          text = cm.getRange(anchor, head);\\n          var lastState = vim.lastEditInputState || {};\\n          if (lastState.motion == \\\"moveByWords\\\" && !isWhiteSpaceString(text)) {\\n            // Exclude trailing whitespace if the range is not all whitespace.\\n            var match = (/\\\\s+$/).exec(text);\\n            if (match && lastState.motionArgs && lastState.motionArgs.forward) {\\n              head = offsetCursor(head, 0, - match[0].length);\\n              text = text.slice(0, - match[0].length);\\n            }\\n          }\\n          var prevLineEnd = new Pos(anchor.line - 1, Number.MAX_VALUE);\\n          var wasLastLine = cm.firstLine() == cm.lastLine();\\n          if (head.line > cm.lastLine() && args.linewise && !wasLastLine) {\\n            cm.replaceRange('', prevLineEnd, head);\\n          } else {\\n            cm.replaceRange('', anchor, head);\\n          }\\n          if (args.linewise) {\\n            // Push the next line back down, if there is a next line.\\n            if (!wasLastLine) {\\n              cm.setCursor(prevLineEnd);\\n              CodeMirror.commands.newlineAndIndent(cm);\\n            }\\n            // make sure cursor ends up at the end of the line.\\n            anchor.ch = Number.MAX_VALUE;\\n          }\\n          finalHead = anchor;\\n        } else if (args.fullLine) {\\n            head.ch = Number.MAX_VALUE;\\n            head.line--;\\n            cm.setSelection(anchor, head)\\n            text = cm.getSelection();\\n            cm.replaceSelection(\\\"\\\");\\n            finalHead = anchor;\\n        } else {\\n          text = cm.getSelection();\\n          var replacement = fillArray('', ranges.length);\\n          cm.replaceSelections(replacement);\\n          finalHead = cursorMin(ranges[0].head, ranges[0].anchor);\\n        }\\n        vimGlobalState.registerController.pushText(\\n            args.registerName, 'change', text,\\n            args.linewise, ranges.length > 1);\\n        actions.enterInsertMode(cm, {head: finalHead}, cm.state.vim);\\n      },\\n      // delete is a javascript keyword.\\n      'delete': function(cm, args, ranges) {\\n        var finalHead, text;\\n        var vim = cm.state.vim;\\n        if (!vim.visualBlock) {\\n          var anchor = ranges[0].anchor,\\n              head = ranges[0].head;\\n          if (args.linewise &&\\n              head.line != cm.firstLine() &&\\n              anchor.line == cm.lastLine() &&\\n              anchor.line == head.line - 1) {\\n            // Special case for dd on last line (and first line).\\n            if (anchor.line == cm.firstLine()) {\\n              anchor.ch = 0;\\n            } else {\\n              anchor = Pos(anchor.line - 1, lineLength(cm, anchor.line - 1));\\n            }\\n          }\\n          text = cm.getRange(anchor, head);\\n          cm.replaceRange('', anchor, head);\\n          finalHead = anchor;\\n          if (args.linewise) {\\n            finalHead = motions.moveToFirstNonWhiteSpaceCharacter(cm, anchor);\\n          }\\n        } else {\\n          text = cm.getSelection();\\n          var replacement = fillArray('', ranges.length);\\n          cm.replaceSelections(replacement);\\n          finalHead = ranges[0].anchor;\\n        }\\n        vimGlobalState.registerController.pushText(\\n            args.registerName, 'delete', text,\\n            args.linewise, vim.visualBlock);\\n        return clipCursorToContent(cm, finalHead);\\n      },\\n      indent: function(cm, args, ranges) {\\n        var vim = cm.state.vim;\\n        var startLine = ranges[0].anchor.line;\\n        var endLine = vim.visualBlock ?\\n          ranges[ranges.length - 1].anchor.line :\\n          ranges[0].head.line;\\n        // In visual mode, n> shifts the selection right n times, instead of\\n        // shifting n lines right once.\\n        var repeat = (vim.visualMode) ? args.repeat : 1;\\n        if (args.linewise) {\\n          // The only way to delete a newline is to delete until the start of\\n          // the next line, so in linewise mode evalInput will include the next\\n          // line. We don't want this in indent, so we go back a line.\\n          endLine--;\\n        }\\n        for (var i = startLine; i <= endLine; i++) {\\n          for (var j = 0; j < repeat; j++) {\\n            cm.indentLine(i, args.indentRight);\\n          }\\n        }\\n        return motions.moveToFirstNonWhiteSpaceCharacter(cm, ranges[0].anchor);\\n      },\\n      indentAuto: function(cm, _args, ranges) {\\n        cm.execCommand(\\\"indentAuto\\\");\\n        return motions.moveToFirstNonWhiteSpaceCharacter(cm, ranges[0].anchor);\\n      },\\n      changeCase: function(cm, args, ranges, oldAnchor, newHead) {\\n        var selections = cm.getSelections();\\n        var swapped = [];\\n        var toLower = args.toLower;\\n        for (var j = 0; j < selections.length; j++) {\\n          var toSwap = selections[j];\\n          var text = '';\\n          if (toLower === true) {\\n            text = toSwap.toLowerCase();\\n          } else if (toLower === false) {\\n            text = toSwap.toUpperCase();\\n          } else {\\n            for (var i = 0; i < toSwap.length; i++) {\\n              var character = toSwap.charAt(i);\\n              text += isUpperCase(character) ? character.toLowerCase() :\\n                  character.toUpperCase();\\n            }\\n          }\\n          swapped.push(text);\\n        }\\n        cm.replaceSelections(swapped);\\n        if (args.shouldMoveCursor){\\n          return newHead;\\n        } else if (!cm.state.vim.visualMode && args.linewise && ranges[0].anchor.line + 1 == ranges[0].head.line) {\\n          return motions.moveToFirstNonWhiteSpaceCharacter(cm, oldAnchor);\\n        } else if (args.linewise){\\n          return oldAnchor;\\n        } else {\\n          return cursorMin(ranges[0].anchor, ranges[0].head);\\n        }\\n      },\\n      yank: function(cm, args, ranges, oldAnchor) {\\n        var vim = cm.state.vim;\\n        var text = cm.getSelection();\\n        var endPos = vim.visualMode\\n          ? cursorMin(vim.sel.anchor, vim.sel.head, ranges[0].head, ranges[0].anchor)\\n          : oldAnchor;\\n        vimGlobalState.registerController.pushText(\\n            args.registerName, 'yank',\\n            text, args.linewise, vim.visualBlock);\\n        return endPos;\\n      }\\n    };\\n\\n    function defineOperator(name, fn) {\\n      operators[name] = fn;\\n    }\\n\\n    var actions = {\\n      jumpListWalk: function(cm, actionArgs, vim) {\\n        if (vim.visualMode) {\\n          return;\\n        }\\n        var repeat = actionArgs.repeat;\\n        var forward = actionArgs.forward;\\n        var jumpList = vimGlobalState.jumpList;\\n\\n        var mark = jumpList.move(cm, forward ? repeat : -repeat);\\n        var markPos = mark ? mark.find() : undefined;\\n        markPos = markPos ? markPos : cm.getCursor();\\n        cm.setCursor(markPos);\\n      },\\n      scroll: function(cm, actionArgs, vim) {\\n        if (vim.visualMode) {\\n          return;\\n        }\\n        var repeat = actionArgs.repeat || 1;\\n        var lineHeight = cm.defaultTextHeight();\\n        var top = cm.getScrollInfo().top;\\n        var delta = lineHeight * repeat;\\n        var newPos = actionArgs.forward ? top + delta : top - delta;\\n        var cursor = copyCursor(cm.getCursor());\\n        var cursorCoords = cm.charCoords(cursor, 'local');\\n        if (actionArgs.forward) {\\n          if (newPos > cursorCoords.top) {\\n             cursor.line += (newPos - cursorCoords.top) / lineHeight;\\n             cursor.line = Math.ceil(cursor.line);\\n             cm.setCursor(cursor);\\n             cursorCoords = cm.charCoords(cursor, 'local');\\n             cm.scrollTo(null, cursorCoords.top);\\n          } else {\\n             // Cursor stays within bounds.  Just reposition the scroll window.\\n             cm.scrollTo(null, newPos);\\n          }\\n        } else {\\n          var newBottom = newPos + cm.getScrollInfo().clientHeight;\\n          if (newBottom < cursorCoords.bottom) {\\n             cursor.line -= (cursorCoords.bottom - newBottom) / lineHeight;\\n             cursor.line = Math.floor(cursor.line);\\n             cm.setCursor(cursor);\\n             cursorCoords = cm.charCoords(cursor, 'local');\\n             cm.scrollTo(\\n                 null, cursorCoords.bottom - cm.getScrollInfo().clientHeight);\\n          } else {\\n             // Cursor stays within bounds.  Just reposition the scroll window.\\n             cm.scrollTo(null, newPos);\\n          }\\n        }\\n      },\\n      scrollToCursor: function(cm, actionArgs) {\\n        var lineNum = cm.getCursor().line;\\n        var charCoords = cm.charCoords(Pos(lineNum, 0), 'local');\\n        var height = cm.getScrollInfo().clientHeight;\\n        var y = charCoords.top;\\n        var lineHeight = charCoords.bottom - y;\\n        switch (actionArgs.position) {\\n          case 'center': y = y - (height / 2) + lineHeight;\\n            break;\\n          case 'bottom': y = y - height + lineHeight;\\n            break;\\n        }\\n        cm.scrollTo(null, y);\\n      },\\n      replayMacro: function(cm, actionArgs, vim) {\\n        var registerName = actionArgs.selectedCharacter;\\n        var repeat = actionArgs.repeat;\\n        var macroModeState = vimGlobalState.macroModeState;\\n        if (registerName == '@') {\\n          registerName = macroModeState.latestRegister;\\n        } else {\\n          macroModeState.latestRegister = registerName;\\n        }\\n        while(repeat--){\\n          executeMacroRegister(cm, vim, macroModeState, registerName);\\n        }\\n      },\\n      enterMacroRecordMode: function(cm, actionArgs) {\\n        var macroModeState = vimGlobalState.macroModeState;\\n        var registerName = actionArgs.selectedCharacter;\\n        if (vimGlobalState.registerController.isValidRegister(registerName)) {\\n          macroModeState.enterMacroRecordMode(cm, registerName);\\n        }\\n      },\\n      toggleOverwrite: function(cm) {\\n        if (!cm.state.overwrite) {\\n          cm.toggleOverwrite(true);\\n          cm.setOption('keyMap', 'vim-replace');\\n          CodeMirror.signal(cm, \\\"vim-mode-change\\\", {mode: \\\"replace\\\"});\\n        } else {\\n          cm.toggleOverwrite(false);\\n          cm.setOption('keyMap', 'vim-insert');\\n          CodeMirror.signal(cm, \\\"vim-mode-change\\\", {mode: \\\"insert\\\"});\\n        }\\n      },\\n      enterInsertMode: function(cm, actionArgs, vim) {\\n        if (cm.getOption('readOnly')) { return; }\\n        vim.insertMode = true;\\n        vim.insertModeRepeat = actionArgs && actionArgs.repeat || 1;\\n        var insertAt = (actionArgs) ? actionArgs.insertAt : null;\\n        var sel = vim.sel;\\n        var head = actionArgs.head || cm.getCursor('head');\\n        var height = cm.listSelections().length;\\n        if (insertAt == 'eol') {\\n          head = Pos(head.line, lineLength(cm, head.line));\\n        } else if (insertAt == 'bol') {\\n          head = Pos(head.line, 0);\\n        } else if (insertAt == 'charAfter') {\\n          head = offsetCursor(head, 0, 1);\\n        } else if (insertAt == 'firstNonBlank') {\\n          head = motions.moveToFirstNonWhiteSpaceCharacter(cm, head);\\n        } else if (insertAt == 'startOfSelectedArea') {\\n          if (!vim.visualMode)\\n              return;\\n          if (!vim.visualBlock) {\\n            if (sel.head.line < sel.anchor.line) {\\n              head = sel.head;\\n            } else {\\n              head = Pos(sel.anchor.line, 0);\\n            }\\n          } else {\\n            head = Pos(\\n                Math.min(sel.head.line, sel.anchor.line),\\n                Math.min(sel.head.ch, sel.anchor.ch));\\n            height = Math.abs(sel.head.line - sel.anchor.line) + 1;\\n          }\\n        } else if (insertAt == 'endOfSelectedArea') {\\n            if (!vim.visualMode)\\n              return;\\n          if (!vim.visualBlock) {\\n            if (sel.head.line >= sel.anchor.line) {\\n              head = offsetCursor(sel.head, 0, 1);\\n            } else {\\n              head = Pos(sel.anchor.line, 0);\\n            }\\n          } else {\\n            head = Pos(\\n                Math.min(sel.head.line, sel.anchor.line),\\n                Math.max(sel.head.ch + 1, sel.anchor.ch));\\n            height = Math.abs(sel.head.line - sel.anchor.line) + 1;\\n          }\\n        } else if (insertAt == 'inplace') {\\n          if (vim.visualMode){\\n            return;\\n          }\\n        } else if (insertAt == 'lastEdit') {\\n          head = getLastEditPos(cm) || head;\\n        }\\n        cm.setOption('disableInput', false);\\n        if (actionArgs && actionArgs.replace) {\\n          // Handle Replace-mode as a special case of insert mode.\\n          cm.toggleOverwrite(true);\\n          cm.setOption('keyMap', 'vim-replace');\\n          CodeMirror.signal(cm, \\\"vim-mode-change\\\", {mode: \\\"replace\\\"});\\n        } else {\\n          cm.toggleOverwrite(false);\\n          cm.setOption('keyMap', 'vim-insert');\\n          CodeMirror.signal(cm, \\\"vim-mode-change\\\", {mode: \\\"insert\\\"});\\n        }\\n        if (!vimGlobalState.macroModeState.isPlaying) {\\n          // Only record if not replaying.\\n          cm.on('change', onChange);\\n          CodeMirror.on(cm.getInputField(), 'keydown', onKeyEventTargetKeyDown);\\n        }\\n        if (vim.visualMode) {\\n          exitVisualMode(cm);\\n        }\\n        selectForInsert(cm, head, height);\\n      },\\n      toggleVisualMode: function(cm, actionArgs, vim) {\\n        var repeat = actionArgs.repeat;\\n        var anchor = cm.getCursor();\\n        var head;\\n        // TODO: The repeat should actually select number of characters/lines\\n        //     equal to the repeat times the size of the previous visual\\n        //     operation.\\n        if (!vim.visualMode) {\\n          // Entering visual mode\\n          vim.visualMode = true;\\n          vim.visualLine = !!actionArgs.linewise;\\n          vim.visualBlock = !!actionArgs.blockwise;\\n          head = clipCursorToContent(\\n              cm, Pos(anchor.line, anchor.ch + repeat - 1));\\n          vim.sel = {\\n            anchor: anchor,\\n            head: head\\n          };\\n          CodeMirror.signal(cm, \\\"vim-mode-change\\\", {mode: \\\"visual\\\", subMode: vim.visualLine ? \\\"linewise\\\" : vim.visualBlock ? \\\"blockwise\\\" : \\\"\\\"});\\n          updateCmSelection(cm);\\n          updateMark(cm, vim, '<', cursorMin(anchor, head));\\n          updateMark(cm, vim, '>', cursorMax(anchor, head));\\n        } else if (vim.visualLine ^ actionArgs.linewise ||\\n            vim.visualBlock ^ actionArgs.blockwise) {\\n          // Toggling between modes\\n          vim.visualLine = !!actionArgs.linewise;\\n          vim.visualBlock = !!actionArgs.blockwise;\\n          CodeMirror.signal(cm, \\\"vim-mode-change\\\", {mode: \\\"visual\\\", subMode: vim.visualLine ? \\\"linewise\\\" : vim.visualBlock ? \\\"blockwise\\\" : \\\"\\\"});\\n          updateCmSelection(cm);\\n        } else {\\n          exitVisualMode(cm);\\n        }\\n      },\\n      reselectLastSelection: function(cm, _actionArgs, vim) {\\n        var lastSelection = vim.lastSelection;\\n        if (vim.visualMode) {\\n          updateLastSelection(cm, vim);\\n        }\\n        if (lastSelection) {\\n          var anchor = lastSelection.anchorMark.find();\\n          var head = lastSelection.headMark.find();\\n          if (!anchor || !head) {\\n            // If the marks have been destroyed due to edits, do nothing.\\n            return;\\n          }\\n          vim.sel = {\\n            anchor: anchor,\\n            head: head\\n          };\\n          vim.visualMode = true;\\n          vim.visualLine = lastSelection.visualLine;\\n          vim.visualBlock = lastSelection.visualBlock;\\n          updateCmSelection(cm);\\n          updateMark(cm, vim, '<', cursorMin(anchor, head));\\n          updateMark(cm, vim, '>', cursorMax(anchor, head));\\n          CodeMirror.signal(cm, 'vim-mode-change', {\\n            mode: 'visual',\\n            subMode: vim.visualLine ? 'linewise' :\\n                     vim.visualBlock ? 'blockwise' : ''});\\n        }\\n      },\\n      joinLines: function(cm, actionArgs, vim) {\\n        var curStart, curEnd;\\n        if (vim.visualMode) {\\n          curStart = cm.getCursor('anchor');\\n          curEnd = cm.getCursor('head');\\n          if (cursorIsBefore(curEnd, curStart)) {\\n            var tmp = curEnd;\\n            curEnd = curStart;\\n            curStart = tmp;\\n          }\\n          curEnd.ch = lineLength(cm, curEnd.line) - 1;\\n        } else {\\n          // Repeat is the number of lines to join. Minimum 2 lines.\\n          var repeat = Math.max(actionArgs.repeat, 2);\\n          curStart = cm.getCursor();\\n          curEnd = clipCursorToContent(cm, Pos(curStart.line + repeat - 1,\\n                                               Infinity));\\n        }\\n        var finalCh = 0;\\n        for (var i = curStart.line; i < curEnd.line; i++) {\\n          finalCh = lineLength(cm, curStart.line);\\n          var tmp = Pos(curStart.line + 1,\\n                        lineLength(cm, curStart.line + 1));\\n          var text = cm.getRange(curStart, tmp);\\n          text = actionArgs.keepSpaces\\n            ? text.replace(/\\\\n\\\\r?/g, '')\\n            : text.replace(/\\\\n\\\\s*/g, ' ');\\n          cm.replaceRange(text, curStart, tmp);\\n        }\\n        var curFinalPos = Pos(curStart.line, finalCh);\\n        if (vim.visualMode) {\\n          exitVisualMode(cm, false);\\n        }\\n        cm.setCursor(curFinalPos);\\n      },\\n      newLineAndEnterInsertMode: function(cm, actionArgs, vim) {\\n        vim.insertMode = true;\\n        var insertAt = copyCursor(cm.getCursor());\\n        if (insertAt.line === cm.firstLine() && !actionArgs.after) {\\n          // Special case for inserting newline before start of document.\\n          cm.replaceRange('\\\\n', Pos(cm.firstLine(), 0));\\n          cm.setCursor(cm.firstLine(), 0);\\n        } else {\\n          insertAt.line = (actionArgs.after) ? insertAt.line :\\n              insertAt.line - 1;\\n          insertAt.ch = lineLength(cm, insertAt.line);\\n          cm.setCursor(insertAt);\\n          var newlineFn = CodeMirror.commands.newlineAndIndentContinueComment ||\\n              CodeMirror.commands.newlineAndIndent;\\n          newlineFn(cm);\\n        }\\n        this.enterInsertMode(cm, { repeat: actionArgs.repeat }, vim);\\n      },\\n      paste: function(cm, actionArgs, vim) {\\n        var cur = copyCursor(cm.getCursor());\\n        var register = vimGlobalState.registerController.getRegister(\\n            actionArgs.registerName);\\n        var text = register.toString();\\n        if (!text) {\\n          return;\\n        }\\n        if (actionArgs.matchIndent) {\\n          var tabSize = cm.getOption(\\\"tabSize\\\");\\n          // length that considers tabs and tabSize\\n          var whitespaceLength = function(str) {\\n            var tabs = (str.split(\\\"\\\\t\\\").length - 1);\\n            var spaces = (str.split(\\\" \\\").length - 1);\\n            return tabs * tabSize + spaces * 1;\\n          };\\n          var currentLine = cm.getLine(cm.getCursor().line);\\n          var indent = whitespaceLength(currentLine.match(/^\\\\s*/)[0]);\\n          // chomp last newline b/c don't want it to match /^\\\\s*/gm\\n          var chompedText = text.replace(/\\\\n$/, '');\\n          var wasChomped = text !== chompedText;\\n          var firstIndent = whitespaceLength(text.match(/^\\\\s*/)[0]);\\n          var text = chompedText.replace(/^\\\\s*/gm, function(wspace) {\\n            var newIndent = indent + (whitespaceLength(wspace) - firstIndent);\\n            if (newIndent < 0) {\\n              return \\\"\\\";\\n            }\\n            else if (cm.getOption(\\\"indentWithTabs\\\")) {\\n              var quotient = Math.floor(newIndent / tabSize);\\n              return Array(quotient + 1).join('\\\\t');\\n            }\\n            else {\\n              return Array(newIndent + 1).join(' ');\\n            }\\n          });\\n          text += wasChomped ? \\\"\\\\n\\\" : \\\"\\\";\\n        }\\n        if (actionArgs.repeat > 1) {\\n          var text = Array(actionArgs.repeat + 1).join(text);\\n        }\\n        var linewise = register.linewise;\\n        var blockwise = register.blockwise;\\n        if (blockwise) {\\n          text = text.split('\\\\n');\\n          if (linewise) {\\n              text.pop();\\n          }\\n          for (var i = 0; i < text.length; i++) {\\n            text[i] = (text[i] == '') ? ' ' : text[i];\\n          }\\n          cur.ch += actionArgs.after ? 1 : 0;\\n          cur.ch = Math.min(lineLength(cm, cur.line), cur.ch);\\n        } else if (linewise) {\\n          if(vim.visualMode) {\\n            text = vim.visualLine ? text.slice(0, -1) : '\\\\n' + text.slice(0, text.length - 1) + '\\\\n';\\n          } else if (actionArgs.after) {\\n            // Move the newline at the end to the start instead, and paste just\\n            // before the newline character of the line we are on right now.\\n            text = '\\\\n' + text.slice(0, text.length - 1);\\n            cur.ch = lineLength(cm, cur.line);\\n          } else {\\n            cur.ch = 0;\\n          }\\n        } else {\\n          cur.ch += actionArgs.after ? 1 : 0;\\n        }\\n        var curPosFinal;\\n        var idx;\\n        if (vim.visualMode) {\\n          //  save the pasted text for reselection if the need arises\\n          vim.lastPastedText = text;\\n          var lastSelectionCurEnd;\\n          var selectedArea = getSelectedAreaRange(cm, vim);\\n          var selectionStart = selectedArea[0];\\n          var selectionEnd = selectedArea[1];\\n          var selectedText = cm.getSelection();\\n          var selections = cm.listSelections();\\n          var emptyStrings = new Array(selections.length).join('1').split('1');\\n          // save the curEnd marker before it get cleared due to cm.replaceRange.\\n          if (vim.lastSelection) {\\n            lastSelectionCurEnd = vim.lastSelection.headMark.find();\\n          }\\n          // push the previously selected text to unnamed register\\n          vimGlobalState.registerController.unnamedRegister.setText(selectedText);\\n          if (blockwise) {\\n            // first delete the selected text\\n            cm.replaceSelections(emptyStrings);\\n            // Set new selections as per the block length of the yanked text\\n            selectionEnd = Pos(selectionStart.line + text.length-1, selectionStart.ch);\\n            cm.setCursor(selectionStart);\\n            selectBlock(cm, selectionEnd);\\n            cm.replaceSelections(text);\\n            curPosFinal = selectionStart;\\n          } else if (vim.visualBlock) {\\n            cm.replaceSelections(emptyStrings);\\n            cm.setCursor(selectionStart);\\n            cm.replaceRange(text, selectionStart, selectionStart);\\n            curPosFinal = selectionStart;\\n          } else {\\n            cm.replaceRange(text, selectionStart, selectionEnd);\\n            curPosFinal = cm.posFromIndex(cm.indexFromPos(selectionStart) + text.length - 1);\\n          }\\n          // restore the the curEnd marker\\n          if(lastSelectionCurEnd) {\\n            vim.lastSelection.headMark = cm.setBookmark(lastSelectionCurEnd);\\n          }\\n          if (linewise) {\\n            curPosFinal.ch=0;\\n          }\\n        } else {\\n          if (blockwise) {\\n            cm.setCursor(cur);\\n            for (var i = 0; i < text.length; i++) {\\n              var line = cur.line+i;\\n              if (line > cm.lastLine()) {\\n                cm.replaceRange('\\\\n',  Pos(line, 0));\\n              }\\n              var lastCh = lineLength(cm, line);\\n              if (lastCh < cur.ch) {\\n                extendLineToColumn(cm, line, cur.ch);\\n              }\\n            }\\n            cm.setCursor(cur);\\n            selectBlock(cm, Pos(cur.line + text.length-1, cur.ch));\\n            cm.replaceSelections(text);\\n            curPosFinal = cur;\\n          } else {\\n            cm.replaceRange(text, cur);\\n            // Now fine tune the cursor to where we want it.\\n            if (linewise && actionArgs.after) {\\n              curPosFinal = Pos(\\n              cur.line + 1,\\n              findFirstNonWhiteSpaceCharacter(cm.getLine(cur.line + 1)));\\n            } else if (linewise && !actionArgs.after) {\\n              curPosFinal = Pos(\\n                cur.line,\\n                findFirstNonWhiteSpaceCharacter(cm.getLine(cur.line)));\\n            } else if (!linewise && actionArgs.after) {\\n              idx = cm.indexFromPos(cur);\\n              curPosFinal = cm.posFromIndex(idx + text.length - 1);\\n            } else {\\n              idx = cm.indexFromPos(cur);\\n              curPosFinal = cm.posFromIndex(idx + text.length);\\n            }\\n          }\\n        }\\n        if (vim.visualMode) {\\n          exitVisualMode(cm, false);\\n        }\\n        cm.setCursor(curPosFinal);\\n      },\\n      undo: function(cm, actionArgs) {\\n        cm.operation(function() {\\n          repeatFn(cm, CodeMirror.commands.undo, actionArgs.repeat)();\\n          cm.setCursor(cm.getCursor('anchor'));\\n        });\\n      },\\n      redo: function(cm, actionArgs) {\\n        repeatFn(cm, CodeMirror.commands.redo, actionArgs.repeat)();\\n      },\\n      setRegister: function(_cm, actionArgs, vim) {\\n        vim.inputState.registerName = actionArgs.selectedCharacter;\\n      },\\n      setMark: function(cm, actionArgs, vim) {\\n        var markName = actionArgs.selectedCharacter;\\n        updateMark(cm, vim, markName, cm.getCursor());\\n      },\\n      replace: function(cm, actionArgs, vim) {\\n        var replaceWith = actionArgs.selectedCharacter;\\n        var curStart = cm.getCursor();\\n        var replaceTo;\\n        var curEnd;\\n        var selections = cm.listSelections();\\n        if (vim.visualMode) {\\n          curStart = cm.getCursor('start');\\n          curEnd = cm.getCursor('end');\\n        } else {\\n          var line = cm.getLine(curStart.line);\\n          replaceTo = curStart.ch + actionArgs.repeat;\\n          if (replaceTo > line.length) {\\n            replaceTo=line.length;\\n          }\\n          curEnd = Pos(curStart.line, replaceTo);\\n        }\\n        if (replaceWith=='\\\\n') {\\n          if (!vim.visualMode) cm.replaceRange('', curStart, curEnd);\\n          // special case, where vim help says to replace by just one line-break\\n          (CodeMirror.commands.newlineAndIndentContinueComment || CodeMirror.commands.newlineAndIndent)(cm);\\n        } else {\\n          var replaceWithStr = cm.getRange(curStart, curEnd);\\n          //replace all characters in range by selected, but keep linebreaks\\n          replaceWithStr = replaceWithStr.replace(/[^\\\\n]/g, replaceWith);\\n          if (vim.visualBlock) {\\n            // Tabs are split in visua block before replacing\\n            var spaces = new Array(cm.getOption(\\\"tabSize\\\")+1).join(' ');\\n            replaceWithStr = cm.getSelection();\\n            replaceWithStr = replaceWithStr.replace(/\\\\t/g, spaces).replace(/[^\\\\n]/g, replaceWith).split('\\\\n');\\n            cm.replaceSelections(replaceWithStr);\\n          } else {\\n            cm.replaceRange(replaceWithStr, curStart, curEnd);\\n          }\\n          if (vim.visualMode) {\\n            curStart = cursorIsBefore(selections[0].anchor, selections[0].head) ?\\n                         selections[0].anchor : selections[0].head;\\n            cm.setCursor(curStart);\\n            exitVisualMode(cm, false);\\n          } else {\\n            cm.setCursor(offsetCursor(curEnd, 0, -1));\\n          }\\n        }\\n      },\\n      incrementNumberToken: function(cm, actionArgs) {\\n        var cur = cm.getCursor();\\n        var lineStr = cm.getLine(cur.line);\\n        var re = /(-?)(?:(0x)([\\\\da-f]+)|(0b|0|)(\\\\d+))/gi;\\n        var match;\\n        var start;\\n        var end;\\n        var numberStr;\\n        while ((match = re.exec(lineStr)) !== null) {\\n          start = match.index;\\n          end = start + match[0].length;\\n          if (cur.ch < end)break;\\n        }\\n        if (!actionArgs.backtrack && (end <= cur.ch))return;\\n        if (match) {\\n          var baseStr = match[2] || match[4]\\n          var digits = match[3] || match[5]\\n          var increment = actionArgs.increase ? 1 : -1;\\n          var base = {'0b': 2, '0': 8, '': 10, '0x': 16}[baseStr.toLowerCase()];\\n          var number = parseInt(match[1] + digits, base) + (increment * actionArgs.repeat);\\n          numberStr = number.toString(base);\\n          var zeroPadding = baseStr ? new Array(digits.length - numberStr.length + 1 + match[1].length).join('0') : ''\\n          if (numberStr.charAt(0) === '-') {\\n            numberStr = '-' + baseStr + zeroPadding + numberStr.substr(1);\\n          } else {\\n            numberStr = baseStr + zeroPadding + numberStr;\\n          }\\n          var from = Pos(cur.line, start);\\n          var to = Pos(cur.line, end);\\n          cm.replaceRange(numberStr, from, to);\\n        } else {\\n          return;\\n        }\\n        cm.setCursor(Pos(cur.line, start + numberStr.length - 1));\\n      },\\n      repeatLastEdit: function(cm, actionArgs, vim) {\\n        var lastEditInputState = vim.lastEditInputState;\\n        if (!lastEditInputState) { return; }\\n        var repeat = actionArgs.repeat;\\n        if (repeat && actionArgs.repeatIsExplicit) {\\n          vim.lastEditInputState.repeatOverride = repeat;\\n        } else {\\n          repeat = vim.lastEditInputState.repeatOverride || repeat;\\n        }\\n        repeatLastEdit(cm, vim, repeat, false /** repeatForInsert */);\\n      },\\n      indent: function(cm, actionArgs) {\\n        cm.indentLine(cm.getCursor().line, actionArgs.indentRight);\\n      },\\n      exitInsertMode: exitInsertMode\\n    };\\n\\n    function defineAction(name, fn) {\\n      actions[name] = fn;\\n    }\\n\\n    /*\\n     * Below are miscellaneous utility functions used by vim.js\\n     */\\n\\n    /**\\n     * Clips cursor to ensure that line is within the buffer's range\\n     * If includeLineBreak is true, then allow cur.ch == lineLength.\\n     */\\n    function clipCursorToContent(cm, cur) {\\n      var vim = cm.state.vim;\\n      var includeLineBreak = vim.insertMode || vim.visualMode;\\n      var line = Math.min(Math.max(cm.firstLine(), cur.line), cm.lastLine() );\\n      var maxCh = lineLength(cm, line) - 1 + !!includeLineBreak;\\n      var ch = Math.min(Math.max(0, cur.ch), maxCh);\\n      return Pos(line, ch);\\n    }\\n    function copyArgs(args) {\\n      var ret = {};\\n      for (var prop in args) {\\n        if (args.hasOwnProperty(prop)) {\\n          ret[prop] = args[prop];\\n        }\\n      }\\n      return ret;\\n    }\\n    function offsetCursor(cur, offsetLine, offsetCh) {\\n      if (typeof offsetLine === 'object') {\\n        offsetCh = offsetLine.ch;\\n        offsetLine = offsetLine.line;\\n      }\\n      return Pos(cur.line + offsetLine, cur.ch + offsetCh);\\n    }\\n    function commandMatches(keys, keyMap, context, inputState) {\\n      // Partial matches are not applied. They inform the key handler\\n      // that the current key sequence is a subsequence of a valid key\\n      // sequence, so that the key buffer is not cleared.\\n      var match, partial = [], full = [];\\n      for (var i = 0; i < keyMap.length; i++) {\\n        var command = keyMap[i];\\n        if (context == 'insert' && command.context != 'insert' ||\\n            command.context && command.context != context ||\\n            inputState.operator && command.type == 'action' ||\\n            !(match = commandMatch(keys, command.keys))) { continue; }\\n        if (match == 'partial') { partial.push(command); }\\n        if (match == 'full') { full.push(command); }\\n      }\\n      return {\\n        partial: partial.length && partial,\\n        full: full.length && full\\n      };\\n    }\\n    function commandMatch(pressed, mapped) {\\n      if (mapped.slice(-11) == '<character>') {\\n        // Last character matches anything.\\n        var prefixLen = mapped.length - 11;\\n        var pressedPrefix = pressed.slice(0, prefixLen);\\n        var mappedPrefix = mapped.slice(0, prefixLen);\\n        return pressedPrefix == mappedPrefix && pressed.length > prefixLen ? 'full' :\\n               mappedPrefix.indexOf(pressedPrefix) == 0 ? 'partial' : false;\\n      } else {\\n        return pressed == mapped ? 'full' :\\n               mapped.indexOf(pressed) == 0 ? 'partial' : false;\\n      }\\n    }\\n    function lastChar(keys) {\\n      var match = /^.*(<[^>]+>)$/.exec(keys);\\n      var selectedCharacter = match ? match[1] : keys.slice(-1);\\n      if (selectedCharacter.length > 1){\\n        switch(selectedCharacter){\\n          case '<CR>':\\n            selectedCharacter='\\\\n';\\n            break;\\n          case '<Space>':\\n            selectedCharacter=' ';\\n            break;\\n          default:\\n            selectedCharacter='';\\n            break;\\n        }\\n      }\\n      return selectedCharacter;\\n    }\\n    function repeatFn(cm, fn, repeat) {\\n      return function() {\\n        for (var i = 0; i < repeat; i++) {\\n          fn(cm);\\n        }\\n      };\\n    }\\n    function copyCursor(cur) {\\n      return Pos(cur.line, cur.ch);\\n    }\\n    function cursorEqual(cur1, cur2) {\\n      return cur1.ch == cur2.ch && cur1.line == cur2.line;\\n    }\\n    function cursorIsBefore(cur1, cur2) {\\n      if (cur1.line < cur2.line) {\\n        return true;\\n      }\\n      if (cur1.line == cur2.line && cur1.ch < cur2.ch) {\\n        return true;\\n      }\\n      return false;\\n    }\\n    function cursorMin(cur1, cur2) {\\n      if (arguments.length > 2) {\\n        cur2 = cursorMin.apply(undefined, Array.prototype.slice.call(arguments, 1));\\n      }\\n      return cursorIsBefore(cur1, cur2) ? cur1 : cur2;\\n    }\\n    function cursorMax(cur1, cur2) {\\n      if (arguments.length > 2) {\\n        cur2 = cursorMax.apply(undefined, Array.prototype.slice.call(arguments, 1));\\n      }\\n      return cursorIsBefore(cur1, cur2) ? cur2 : cur1;\\n    }\\n    function cursorIsBetween(cur1, cur2, cur3) {\\n      // returns true if cur2 is between cur1 and cur3.\\n      var cur1before2 = cursorIsBefore(cur1, cur2);\\n      var cur2before3 = cursorIsBefore(cur2, cur3);\\n      return cur1before2 && cur2before3;\\n    }\\n    function lineLength(cm, lineNum) {\\n      return cm.getLine(lineNum).length;\\n    }\\n    function trim(s) {\\n      if (s.trim) {\\n        return s.trim();\\n      }\\n      return s.replace(/^\\\\s+|\\\\s+$/g, '');\\n    }\\n    function escapeRegex(s) {\\n      return s.replace(/([.?*+$\\\\[\\\\]\\\\/\\\\\\\\(){}|\\\\-])/g, '\\\\\\\\$1');\\n    }\\n    function extendLineToColumn(cm, lineNum, column) {\\n      var endCh = lineLength(cm, lineNum);\\n      var spaces = new Array(column-endCh+1).join(' ');\\n      cm.setCursor(Pos(lineNum, endCh));\\n      cm.replaceRange(spaces, cm.getCursor());\\n    }\\n    // This functions selects a rectangular block\\n    // of text with selectionEnd as any of its corner\\n    // Height of block:\\n    // Difference in selectionEnd.line and first/last selection.line\\n    // Width of the block:\\n    // Distance between selectionEnd.ch and any(first considered here) selection.ch\\n    function selectBlock(cm, selectionEnd) {\\n      var selections = [], ranges = cm.listSelections();\\n      var head = copyCursor(cm.clipPos(selectionEnd));\\n      var isClipped = !cursorEqual(selectionEnd, head);\\n      var curHead = cm.getCursor('head');\\n      var primIndex = getIndex(ranges, curHead);\\n      var wasClipped = cursorEqual(ranges[primIndex].head, ranges[primIndex].anchor);\\n      var max = ranges.length - 1;\\n      var index = max - primIndex > primIndex ? max : 0;\\n      var base = ranges[index].anchor;\\n\\n      var firstLine = Math.min(base.line, head.line);\\n      var lastLine = Math.max(base.line, head.line);\\n      var baseCh = base.ch, headCh = head.ch;\\n\\n      var dir = ranges[index].head.ch - baseCh;\\n      var newDir = headCh - baseCh;\\n      if (dir > 0 && newDir <= 0) {\\n        baseCh++;\\n        if (!isClipped) { headCh--; }\\n      } else if (dir < 0 && newDir >= 0) {\\n        baseCh--;\\n        if (!wasClipped) { headCh++; }\\n      } else if (dir < 0 && newDir == -1) {\\n        baseCh--;\\n        headCh++;\\n      }\\n      for (var line = firstLine; line <= lastLine; line++) {\\n        var range = {anchor: new Pos(line, baseCh), head: new Pos(line, headCh)};\\n        selections.push(range);\\n      }\\n      cm.setSelections(selections);\\n      selectionEnd.ch = headCh;\\n      base.ch = baseCh;\\n      return base;\\n    }\\n    function selectForInsert(cm, head, height) {\\n      var sel = [];\\n      for (var i = 0; i < height; i++) {\\n        var lineHead = offsetCursor(head, i, 0);\\n        sel.push({anchor: lineHead, head: lineHead});\\n      }\\n      cm.setSelections(sel, 0);\\n    }\\n    // getIndex returns the index of the cursor in the selections.\\n    function getIndex(ranges, cursor, end) {\\n      for (var i = 0; i < ranges.length; i++) {\\n        var atAnchor = end != 'head' && cursorEqual(ranges[i].anchor, cursor);\\n        var atHead = end != 'anchor' && cursorEqual(ranges[i].head, cursor);\\n        if (atAnchor || atHead) {\\n          return i;\\n        }\\n      }\\n      return -1;\\n    }\\n    function getSelectedAreaRange(cm, vim) {\\n      var lastSelection = vim.lastSelection;\\n      var getCurrentSelectedAreaRange = function() {\\n        var selections = cm.listSelections();\\n        var start =  selections[0];\\n        var end = selections[selections.length-1];\\n        var selectionStart = cursorIsBefore(start.anchor, start.head) ? start.anchor : start.head;\\n        var selectionEnd = cursorIsBefore(end.anchor, end.head) ? end.head : end.anchor;\\n        return [selectionStart, selectionEnd];\\n      };\\n      var getLastSelectedAreaRange = function() {\\n        var selectionStart = cm.getCursor();\\n        var selectionEnd = cm.getCursor();\\n        var block = lastSelection.visualBlock;\\n        if (block) {\\n          var width = block.width;\\n          var height = block.height;\\n          selectionEnd = Pos(selectionStart.line + height, selectionStart.ch + width);\\n          var selections = [];\\n          // selectBlock creates a 'proper' rectangular block.\\n          // We do not want that in all cases, so we manually set selections.\\n          for (var i = selectionStart.line; i < selectionEnd.line; i++) {\\n            var anchor = Pos(i, selectionStart.ch);\\n            var head = Pos(i, selectionEnd.ch);\\n            var range = {anchor: anchor, head: head};\\n            selections.push(range);\\n          }\\n          cm.setSelections(selections);\\n        } else {\\n          var start = lastSelection.anchorMark.find();\\n          var end = lastSelection.headMark.find();\\n          var line = end.line - start.line;\\n          var ch = end.ch - start.ch;\\n          selectionEnd = {line: selectionEnd.line + line, ch: line ? selectionEnd.ch : ch + selectionEnd.ch};\\n          if (lastSelection.visualLine) {\\n            selectionStart = Pos(selectionStart.line, 0);\\n            selectionEnd = Pos(selectionEnd.line, lineLength(cm, selectionEnd.line));\\n          }\\n          cm.setSelection(selectionStart, selectionEnd);\\n        }\\n        return [selectionStart, selectionEnd];\\n      };\\n      if (!vim.visualMode) {\\n      // In case of replaying the action.\\n        return getLastSelectedAreaRange();\\n      } else {\\n        return getCurrentSelectedAreaRange();\\n      }\\n    }\\n    // Updates the previous selection with the current selection's values. This\\n    // should only be called in visual mode.\\n    function updateLastSelection(cm, vim) {\\n      var anchor = vim.sel.anchor;\\n      var head = vim.sel.head;\\n      // To accommodate the effect of lastPastedText in the last selection\\n      if (vim.lastPastedText) {\\n        head = cm.posFromIndex(cm.indexFromPos(anchor) + vim.lastPastedText.length);\\n        vim.lastPastedText = null;\\n      }\\n      vim.lastSelection = {'anchorMark': cm.setBookmark(anchor),\\n                           'headMark': cm.setBookmark(head),\\n                           'anchor': copyCursor(anchor),\\n                           'head': copyCursor(head),\\n                           'visualMode': vim.visualMode,\\n                           'visualLine': vim.visualLine,\\n                           'visualBlock': vim.visualBlock};\\n    }\\n    function expandSelection(cm, start, end) {\\n      var sel = cm.state.vim.sel;\\n      var head = sel.head;\\n      var anchor = sel.anchor;\\n      var tmp;\\n      if (cursorIsBefore(end, start)) {\\n        tmp = end;\\n        end = start;\\n        start = tmp;\\n      }\\n      if (cursorIsBefore(head, anchor)) {\\n        head = cursorMin(start, head);\\n        anchor = cursorMax(anchor, end);\\n      } else {\\n        anchor = cursorMin(start, anchor);\\n        head = cursorMax(head, end);\\n        head = offsetCursor(head, 0, -1);\\n        if (head.ch == -1 && head.line != cm.first